+    fn search_imports(&self, target: &Url, needle: &Url) -> Vec<&Literal> {
+        let needle_module_name = util::uri_to_path(needle)
+            .file_stem()
+            .unwrap()
+            .to_string_lossy()
+            .to_string();
+        let mut imports = vec![];
