+            self.artifacts.insert(new_uri.clone(), entry);
+            let Some(entry) = self.modules.remove(&old_uri) else {
+                continue;
+            };
+            self.modules.insert(new_uri, entry);
+            if let Some(shared) = self.get_shared() {
+                shared.clear_all();
+            }
+        }
+        self.file_cache.rename_files(&params)?;
