+    inputRange: [0, 1, 2],
+    outputRange: ['-100%', '0%', '-100%'],
+  });
+
+  const transform = [{ translateY }];
+
+  return {
+    leftButtonStyle: { transform },
+    rightButtonStyle: { transform },
