+                             Value::Tuple(
+                                 TupleData::from_data(vec![
+                                     ("version".into(), Value::buff_from(vec![0x00]).unwrap()),
+                                     ("hashbytes".into(), Value::buff_from(vec![0; 20]).unwrap()),
+                                 ]).unwrap(),
